// Verifies X-HealthGen-Signature = sha256=HMAC(secret, timestamp + '.' + body) and a 5-minute timestamp window.
// Requires NODE_FUNCTION_ALLOW_BUILTIN=crypto and the HEALTHGEN_HANDOFF_SECRET environment variable on the n8n host.
const crypto = require('crypto');
const item = $input.first().json;
const headers = item.headers || {};
const ts = headers['x-healthgen-timestamp'] || '';
const sig = headers['x-healthgen-signature'] || '';
const secret = $env.HEALTHGEN_HANDOFF_SECRET || '';
const expected = 'sha256=' + crypto.createHmac('sha256', secret).update(ts + '.' + JSON.stringify(item.body)).digest('hex');
const fresh = Math.abs(Date.now() / 1000 - Number(ts)) < 300;
const valid = secret.length > 0 && fresh && sig.length === expected.length && crypto.timingSafeEqual(Buffer.from(sig), Buffer.from(expected));
const b = item.body || {};
const allowedReasons = ['user_request', 'out_of_scope', 'complaint', 'clinical', 'system_error'];
return [{ json: {
  valid,
  session_ref: String(b.session_ref || '').slice(0, 40),
  audience: b.audience === 'provider' ? 'provider' : 'member',
  reason: allowedReasons.includes(b.reason) ? b.reason : 'user_request',
  topic: String(b.topic || '').slice(0, 200),
  priority: b.reason === 'clinical' || b.reason === 'complaint' ? 'high' : 'normal'
} }];

// Ticket reference. Replace with the create-case call to your CRM (Dynamics 365, Salesforce, ServiceNow).
const j = $input.first().json;
const ticket_ref = 'HO-' + Math.floor(1000 + Math.random() * 9000);
const queue = j.audience === 'provider' ? 'provider-services' : 'care-team';
return [{ json: { ...j, ticket_ref, queue, expected_response: j.priority === 'high' ? 'under 5 minutes during business hours' : 'under 10 minutes during business hours' } }];
